int RecoveryActorMean(const float *input,float *mean){
if(!input||!mean)return -1;
float a[128],b[128];
for(int k=0;k<31;k++){if(!isfinite(input[k]))return -1;a[k]=input[k];}
for(int j=0;j<128;j++){float s=b0[j];for(int k=0;k<31;k++)s+=w0[j*31+k]*a[k];b[j]=s>=0?s:expm1f(s);}
for(int j=0;j<128;j++)a[j]=b[j];
for(int j=0;j<64;j++){float s=b1[j];for(int k=0;k<128;k++)s+=w1[j*128+k]*a[k];b[j]=s>=0?s:expm1f(s);}
for(int j=0;j<64;j++)a[j]=b[j];
for(int j=0;j<32;j++){float s=b2[j];for(int k=0;k<64;k++)s+=w2[j*64+k]*a[k];b[j]=s>=0?s:expm1f(s);}
for(int j=0;j<32;j++)a[j]=b[j];
for(int j=0;j<6;j++){float s=b3[j];for(int k=0;k<32;k++)s+=w3[j*32+k]*a[k];b[j]=tanhf(s);}
for(int j=0;j<6;j++)a[j]=b[j];
for(int j=0;j<6;j++){if(!isfinite(a[j]))return -2;mean[j]=a[j];}return 0;}
int RecoveryActorPhysical(const float *input,float *mean,float *physical){int r=RecoveryActorMean(input,mean);return r?r:RLMotion31DecodeRecoveryMean(mean,physical);}
